import {ReactiveFormsModule} from '@angular/forms';
import {MatDialogTitle,MatDialogContent,MatDialogActions,MatDialogClose} from '@angular/material/dialog';
import {MatInput} from '@angular/material/input';
import {MatButton} from '@angular/material/button';
import { Component, inject, type OnInit } from '@angular/core';
import { MAT_DIALOG_DATA } from '@angular/material/dialog';
import { FormControl, Validators } from '@angular/forms';

export interface TimeRestrictionDialogData {
  title: string;
  content: string;
  remainingTime: number;
  confirmbuttonlabel: string;
  showcancel: boolean;
  cancelbuttonlabel: string;
}

@Component({
  selector: 'time-restriction-dialog',
  templateUrl: './time-restriction-dialog.component.html',
  standalone: true,
  imports: [ReactiveFormsModule,MatDialogTitle,MatDialogContent,MatDialogActions,MatDialogClose,MatInput,MatButton]
})
export class TimeRestrictionDialogComponent implements OnInit {
  readonly dialogData=inject<TimeRestrictionDialogData>(MAT_DIALOG_DATA);
  showcancel: boolean = true;
  setTime = new FormControl(this.dialogData.remainingTime, [Validators.max(this.dialogData.remainingTime)]);



  ngOnInit() {
    if ((typeof this.dialogData.title === 'undefined') || (this.dialogData.title.length === 0)) {
      this.dialogData.title = 'Bitte bestätigen!';
    }
    if (
      (typeof this.dialogData.confirmbuttonlabel === 'undefined') ||
      (this.dialogData.confirmbuttonlabel.length === 0)
    ) {
      this.dialogData.confirmbuttonlabel = 'Bestätigen';
    }
    if (!this.dialogData.showcancel) {
      this.showcancel = false;
    }
    if (
      (typeof this.dialogData.cancelbuttonlabel === 'undefined') ||
      (this.dialogData.cancelbuttonlabel.length === 0)
    ) {
      this.dialogData.cancelbuttonlabel = 'Abbrechen';
    }
  }

  returnValue(): boolean | number {
    if (this.setTime.valid) {
      return this.setTime.value!;
    }
    return false;
  }
}
import {CustomtextService} from '../../shared/services/customtext/customtext.service';
import {NativeMonitorEntriesView} from '../../native-monitor-entries.pipe';
import {inject,LOCALE_ID} from '@angular/core';
import {formatNativeMonitorMinutes} from '../../native-monitor-number';
import { NgTemplateOutlet } from '@angular/common';
import {NativeMonitorIconComponent as MatIcon} from '../../native-monitor-icon.component';
import {MatBadge} from '@angular/material/badge';
import {MatTooltip} from '@angular/material/tooltip';
import {MatCheckbox} from '@angular/material/checkbox';
import {CustomtextPipe} from '../../shared/shared.module';
import {TemplateContextDirective} from '../../shared/directives/template-context.directive';
import {IsCodeClearPipe} from './is-code-clear.pipe';
import {TimeLeftPipe} from './timeleft.pipe';
import {PositionPipe} from './position.pipe';
import {TestletvisiblePipe} from './testletvisible.pipe';
import {
  Component, EventEmitter, Input, Output
} from '@angular/core';
import { MatCheckboxChange } from '@angular/material/checkbox';
import {
  type Testlet, type TestViewDisplayOptions, type Selected, type TestSession, isBooklet, isTestlet, type TestSessionSuperState
} from '../group-monitor.interfaces';
import { TestSessionUtil } from './test-session.util';
import { type IconData, superStates } from './super-states';
import type { UnitDef } from '../../shared/interfaces/booklet.interfaces';

interface TestletContext {
  $implicit: Testlet,
  recursionLevel: number
}

@Component({
  selector: 'tc-test-session',
  templateUrl: './test-session.component.html',
  styleUrls: ['./test-session.component.css'],
  standalone: true,
  imports: [NgTemplateOutlet, MatIcon, MatBadge, MatTooltip, MatCheckbox, TemplateContextDirective]
})
export class TestSessionComponent {
  readonly entries = new NativeMonitorEntriesView().transform;
  private readonly nativeText = new CustomtextPipe(inject(CustomtextService));
  readonly customtext = this.nativeText.transform.bind(this.nativeText);
  readonly timeLeftView = new TimeLeftPipe().transform;
  readonly position = new PositionPipe().transform;
  readonly isCodeClear = new IsCodeClearPipe().transform;
  readonly testletVisible = new TestletvisiblePipe().transform;

  private readonly locale=inject(LOCALE_ID);
  formatRemainingTime(value:number):string{return formatNativeMonitorMinutes(value,this.locale);}
  @Input() testSession!: TestSession;
  @Input() displayOptions!: TestViewDisplayOptions;
  @Input() marked: Selected | null = null;
  @Input() selected: Selected | null = null;
  @Input() checked: boolean = false;
  @Input() bookletStates: { [p: string]: string } = {};

  @Output() markedElement$ = new EventEmitter<Selected>();
  @Output() selectedElement$ = new EventEmitter<Selected>();
  @Output() checked$ = new EventEmitter<boolean>();

  superStateIcons: Partial<Record<TestSessionSuperState, IconData>> = superStates;

  // TODO use pipes for the following functions
  stateString = TestSessionUtil.stateString;
  bookletStateLabel = TestSessionUtil.bookletStateLabel;
  hasState = TestSessionUtil.hasState;
  isBooklet = isBooklet;
  isTestlet = isTestlet;
  // eslint-disable-next-line class-methods-use-this
  trackUnits = (index: number, testlet: Testlet | UnitDef): string => testlet.id || index.toString();

  testletContext?: TestletContext;

  mark(testletOrNull: Testlet | null = null): void {
    if ((testletOrNull != null) && !testletOrNull.blockId) {
      return;
    }
    if (['pending', 'locked'].includes(this.testSession.state)) {
      return;
    }
    this.marked = this.returnAsSelected(testletOrNull);
    this.markedElement$.emit(this.marked);
  }

  isSelectionTheSameBlockAsParentSelection(testletOrNull: Testlet | null = null): boolean {
    return !!testletOrNull && //  is something Nowselected?
      (this.selected?.element?.blockId === testletOrNull?.blockId) && // is nowselected already in parentselection?
      // is nowselected same species as parentselection (is it the same block 1? == same col)
      (this.selected?.originSession.booklet.species === this.testSession.booklet.species);
  }

  returnClicks(testletOrNull: Testlet | null = null): 'first' | 'second' | 'third' {
    const isSelectionInSameSession = this.isSelectionTheSameBlockAsParentSelection(testletOrNull) &&
      // is the nowSelection the same Session (row in Table)
      (this.selected?.originSession.data.testId === this.testSession.data.testId);

    if (isSelectionInSameSession && this.selected?.nthClick === 'first') {
      return 'second';
    }
    if (isSelectionInSameSession && this.selected?.nthClick === 'second') {
      return 'third';
    }
    return 'first';
  }

  isMarked(testletOrNull: Testlet | null = null): boolean {
    return !!testletOrNull &&
      (!['pending', 'locked'].includes(this.testSession.state)) &&
      (this.marked?.element?.blockId === testletOrNull.blockId) &&
      (this.marked?.originSession.booklet.species === this.testSession.booklet.species);
  }

  select(testletOrNull: Testlet | null): void {
    if ((testletOrNull != null) && !testletOrNull.blockId) {
      return;
    }
    this.applySelection(testletOrNull);
  }

  deselect($event: MouseEvent | null): void {
    if ($event && ($event.currentTarget === $event.target)) {
      this.applySelection();
    }
  }

  deselectForce($event: Event): boolean {
    this.applySelection();
    $event.stopImmediatePropagation();
    $event.stopPropagation();
    $event.preventDefault();
    return false;
  }

  invertSelection(): boolean {
    this.applySelection(this.selected?.element, true);
    return false;
  }

  toggleCheckbox($event: MatCheckboxChange): void {
    this.checked$.emit($event.checked);
  }

  private applySelection(testletOrNull: Testlet | null = null, inversion = false): void {
    if (['pending', 'locked'].includes(this.testSession.state)) {
      return;
    }
    this.selected = this.returnAsSelected(testletOrNull, inversion);
    this.selectedElement$.emit(this.selected);
  }

  private returnAsSelected(testletOrNull: Testlet | null = null, inversion = false): Selected {
    return {
      element: testletOrNull,
      originSession: this.testSession,
      nthClick: this.returnClicks(testletOrNull),
      inversion
    };
  }
}

import {originalTestLogIdPrefix} from '@testcenter-rewrite-app/domain';
import {originalMonitorGroupSelection} from './original-monitor-session.js';
import {originalMonitorLockSelection,originalMonitorLockTestNumber} from './original-monitor-lock.js';
import type {OriginalMonitorProfile} from '@testcenter-rewrite-app/contracts';
import type {ParticipantSession} from '@testcenter-rewrite-app/domain';
import {originalMonitorProfileIdsEqual} from './original-monitor-profile.js';
import {originalParticipantGroupKeysEqual} from './original-participant-group.js';
import {parseOriginalTestName} from './original-test.js';
import {readOriginalPerson} from './original-test-access.js';
import type {OriginalAuthenticationPort} from './original-authentication.js';
import type {OriginalMonitorRepository} from './original-monitor-store.js';
import {formatOriginalMonitorSessionsJson, type OriginalMonitorActor} from './original-monitor-session.js';
import {FirstSliceError} from './first-slice-error.js';

export type OriginalMonitorPort = {
  requireMonitor(input: {token: string; groupKey?: string}): Promise<void>;
  changeLocks(input: {token: string; groupKey: string; locked: boolean; body: unknown}): Promise<void>;
  profile(input: {token: string; profileId: string}): Promise<OriginalMonitorProfile>;
  booklet(input: {token: string; bookletName: string}): Promise<string>;
  sessions(input: {token: string; groupKey?: string}): Promise<string>;
};
export function createOriginalMonitorPort(input: {auth: OriginalAuthenticationPort; repository: OriginalMonitorRepository & Pick<import('./index.js').FirstSliceRepository,'appendOriginalTestLogs'>; now:()=>string; id:()=>string;
  profiles: (actor: OriginalMonitorActor) => Promise<OriginalMonitorProfile[] | undefined>;
  assignedBooklets: (person: ParticipantSession) => Promise<string[]>;
  readBooklet: (scope: {tenantId: string; workspaceId: string}, name: string) => Promise<{xml: string}>;
}): OriginalMonitorPort {
  const actor = async (token: string): Promise<OriginalMonitorActor> => {
    const state = await input.auth.read({token});
    if (state.kind !== 'person' || state.participantSession.originalLoginKey === undefined ||
      !['monitor-group', 'monitor-study'].includes(state.participantSession.originalOperationalMode ?? '')) {
      throw new FirstSliceError(403, 'original_monitor_forbidden', 'A current native monitor is required.');
    }
    const person = state.participantSession;
    return {participantSessionId: person.participantSessionId, tenantId: person.tenantId, workspaceId: person.workspaceId,
      originalLoginKey: person.originalLoginKey!, groupKey: person.groupKey, mode: person.originalOperationalMode as OriginalMonitorActor['mode']};
  };
  return {
    async requireMonitor({token,groupKey}) {const monitor=await actor(token);if(groupKey!==undefined)originalMonitorGroupSelection(monitor,groupKey);},
    async changeLocks({token,groupKey,locked,body}) {
      const monitor=await actor(token);originalMonitorGroupSelection(monitor,groupKey);
      for(const value of originalMonitorLockSelection(body)) {
        const testNumber=originalMonitorLockTestNumber(value);
        const {scope,actorPersonNumber}=await input.repository.changeOriginalMonitorTestLock(monitor,groupKey,testNumber,locked,input.now());
        if(locked)await input.repository.appendOriginalTestLogs(scope,[{participantTestLogId:originalTestLogIdPrefix+input.id(),
          tenantId:scope.tenantId,workspaceId:scope.workspaceId,participantSessionId:scope.participantSessionId,testRunId:scope.testRunId,
          unitKey:null,originalUnitId:null,logKey:'locked by monitor',logContent:actorPersonNumber,timestamp:0,originalTimestamp:0,recordedAt:input.now()}]);
      }
    },
    async profile({token, profileId}) {
      const profiles = await input.profiles(await actor(token));
      if (profiles === undefined) throw new FirstSliceError(409, 'original_monitor_profile_history_unknown', 'The original authored profile is unavailable; import its validated Testtakers XML again.');
      const profile = profiles.find(profile => originalMonitorProfileIdsEqual(profile.id, profileId));
      if (!profile) throw new FirstSliceError(404, 'original_monitor_profile_missing', `Profile not found \`${profileId}\``);
      return structuredClone(profile);
    },
    async booklet({token, bookletName}) {
      const person = await readOriginalPerson(input.auth, token);
      const monitor = ['monitor-group', 'monitor-study'].includes(person.originalOperationalMode ?? '');
      if (!monitor && !(await input.assignedBooklets(person)).some(name => originalParticipantGroupKeysEqual(parseOriginalTestName(name).fileId, bookletName))) {
        throw new FirstSliceError(403, 'original_booklet_forbidden', 'The requested Booklet is not assigned to this person.');
      }
      return (await input.readBooklet(person, bookletName)).xml;
    },
